{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "VPC Flow Logs not enabled",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "VPC Flow Logs are not enabled, which means network traffic within the VPC is not being logged. This can hinder the ability to detect and investigate suspicious activity or troubleshoot network issues."
    }
  ],
  "patched_code": "resource \"aws_vpc\" \"changeme_aws_vpc_simple\" {\n  cidr_block = \"10.1.0.0/16\"\n\n  enable_dns_support   = true\n  enable_dns_hostnames = true\n\n  flow_log {\n    traffic_type = \"ALL\"\n    log_destination_type = \"cloud-watch-logs\"\n    log_group_name = \"vpc-flow-logs\"\n  }\n}",
  "fix_summary": "Enabled VPC Flow Logs to log all traffic and added DNS support and hostnames for better network management."
}
